package com.codeguardian.service; import com.codeguardian.repository.*; import com.codeguardian.entity.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*; @Service @RequiredArgsConstructor public class DashboardService{private final ReviewTaskRepository tasks;private final FindingRepository findings;public Map<String,Object> summary(){List<ReviewTask> ts=tasks.findAll();List<Finding> fs=findings.findAll();Map<String,Long> statuses=ts.stream().collect(Collectors.groupingBy(ReviewTask::getStatus,Collectors.counting()));Map<String,Long> severity=fs.stream().collect(Collectors.groupingBy(Finding::getSeverity,Collectors.counting()));return Map.of("taskCount",ts.size(),"findingCount",fs.size(),"statusDistribution",statuses,"severityDistribution",severity,"recentTasks",ts.stream().sorted(Comparator.comparing(ReviewTask::getCreatedAt,Comparator.nullsLast(Comparator.reverseOrder()))).limit(10).toList());}}
